public WHSContainerTypeCode parmWHSContainerTypeCode(WHSContainerTypeCode _containerType = containerType)
{
    containerType = _containerType;
    return containerType;
}

public TFMBackendId parmBackendID(TFMBackendId _backendId = BackendID)
{
    BackendID = _backendId;
    return BackendID;
}

public TFMBackendId parmOrderType(TFMBackendId _orderType = orderType)
{
    orderType = _orderType;
    return orderType;
}

public TFMBackendId parmOrderBackendID(TFMBackendId _backendId = BackendID)
{
    BackendID = _backendId;
    return BackendID;
}

public str parmBin(str _bin = bin)
{
    bin = _bin;
    return bin;
}

public str parmInventlocationid(str _inventlocationid = inventlocationid)
{
    inventlocationid = _inventlocationid;
    return inventlocationid;
}

public str parmLineNumber(str _lineNumber = lineNumber)
{
    lineNumber = _lineNumber;
    return lineNumber;
}

public str parmwmsLocationId(str _wmsLocationId = wmsLocationId)
{
    wmsLocationId = _wmsLocationId;
    return wmsLocationId;
}
